import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>

#define K 3
#define TILE 16
#define REG 4
#define OUT_TILE (TILE * REG)
#define TILE_H (OUT_TILE + K - 1)
#define OC_TILE 4
__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int H_out, int W_out,
    int tiles_w)
{
    extern __shared__ __nv_bfloat16 s_mem[];
    __nv_bfloat16* s_weight = s_mem;                       // size = OC_TILE*C_in*K*K
    __nv_bfloat16* s_input  = s_mem + OC_TILE * C_in * K * K; // size = C_in*TILE_H*TILE_H
    int n  = blockIdx.x;
    int oc_base = blockIdx.y * OC_TILE;
    int tile_idx = blockIdx.z;
    int tile_row = tile_idx / tiles_w;
    int tile_col = tile_idx % tiles_w;
    int oh_base = tile_row * OUT_TILE;
    int ow_base = tile_col * OUT_TILE;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;
    int nthreads = blockDim.x * blockDim.y;
    int wsize_per_oc = C_in * K * K;
    int wsize_total = OC_TILE * wsize_per_oc;
    for (int i = tid; i < wsize_total; i += nthreads) {
        int t = i / wsize_per_oc;
        int rem = i % wsize_per_oc;
        int oc = oc_base + t;
        __nv_bfloat16 wv = __float2bfloat16(0.0f);
        if (oc < C_out) {
            wv = weight[(size_t)oc * wsize_per_oc + rem];
        }
        s_weight[i] = wv;
    }
    const __nv_bfloat16* input_n = input + (size_t)n * C_in * H * W;
    int input_tile_size = TILE_H * TILE_H;
    int total_input_elems = C_in * input_tile_size;
    for (int i = tid; i < total_input_elems; i += nthreads) {
        int c = i / input_tile_size;
        int rem = i % input_tile_size;
        int row = rem / TILE_H;
        int col = rem % TILE_H;
        int ih = oh_base + row;
        int iw = ow_base + col;
        __nv_bfloat16 val = __float2bfloat16(0.0f);
        if (ih < H && iw < W) {
            val = input_n[(size_t)c * H * W + (size_t)ih * W + iw];
        }
        s_input[i] = val;
    }
    __syncthreads();
    int oh0 = oh_base + ty;
    int ow0 = ow_base + tx;
    bool anyValidRow = false;
    #pragma unroll
    for (int r = 0; r < REG; r++) {
        if (oh0 + r * TILE < H_out) { anyValidRow = true; }
    }
    bool anyValidCol = false;
    #pragma unroll
    for (int q = 0; q < REG; q++) {
        if (ow0 + q * TILE < W_out) { anyValidCol = true; }
    }
    if (!anyValidRow || !anyValidCol) return;
    float sum[OC_TILE][REG][REG];
    #pragma unroll
    for (int t = 0; t < OC_TILE; t++) {
        #pragma unroll
        for (int r = 0; r < REG; r++) {
            #pragma unroll
            for (int q = 0; q < REG; q++) {
                sum[t][r][q] = 0.0f;
            }
        }
    }
    for (int c = 0; c < C_in; c++) {
        const __nv_bfloat16* in_c = s_input + c * input_tile_size;
        int wgt_c_off = c * K * K;
        #pragma unroll
        for (int kh = 0; kh < K; kh++) {
            #pragma unroll
            for (int kw = 0; kw < K; kw++) {
                float v[REG][REG];
                #pragma unroll
                for (int r = 0; r < REG; r++) {
                    int row_off = (ty + r * TILE + kh) * TILE_H;
                    #pragma unroll
                    for (int q = 0; q < REG; q++) {
                        v[r][q] = __bfloat162float(in_c[row_off + (tx + q * TILE + kw)]);
                    }
                }
                #pragma unroll
                for (int t = 0; t < OC_TILE; t++) {
                    float w = __bfloat162float(s_weight[t * wsize_per_oc + wgt_c_off + kh * K + kw]);
                    #pragma unroll
                    for (int r = 0; r < REG; r++) {
                        #pragma unroll
                        for (int q = 0; q < REG; q++) {
                            sum[t][r][q] += v[r][q] * w;
                        }
                    }
                }
            }
        }
    }
    #pragma unroll
    for (int t = 0; t < OC_TILE; t++) {
        int oc = oc_base + t;
        if (oc >= C_out) continue;
        size_t out_batch_offset = ((size_t)n * C_out + oc) * H_out * W_out;
        #pragma unroll
        for (int r = 0; r < REG; r++) {
            int oh = oh0 + r * TILE;
            if (oh >= H_out) continue;
            #pragma unroll
            for (int q = 0; q < REG; q++) {
                int ow = ow0 + q * TILE;
                if (ow < W_out) {
                    output[out_batch_offset + (size_t)oh * W_out + ow] = __float2bfloat16(sum[t][r][q]);
                }
            }
        }
    }
}
torch::Tensor conv2d_bf16_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kBFloat16, "input must be bf16");
    TORCH_CHECK(weight.dtype() == torch::kBFloat16, "weight must be bf16");
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int kernel_size = weight.size(2); // assume square, = K
    int H_out = H - kernel_size + 1;
    int W_out = W - kernel_size + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    dim3 block(TILE, TILE);
    int tiles_h = (H_out + OUT_TILE - 1) / OUT_TILE;
    int tiles_w = (W_out + OUT_TILE - 1) / OUT_TILE;
    int oc_tiles = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 grid(N, oc_tiles, tiles_h * tiles_w);
    size_t shmem_size = (size_t)(OC_TILE * C_in * K * K + C_in * TILE_H * TILE_H) * sizeof(__nv_bfloat16);
    cudaFuncSetAttribute(conv2d_bf16_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shmem_size);
    conv2d_bf16_kernel<<<grid, block, shmem_size>>>(
        reinterpret_cast<const __nv_bfloat16*>(input.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        N, C_in, H, W, C_out, H_out, W_out, tiles_w
    );
    return output;
}
"""
cpp_source = r"""
torch::Tensor conv2d_bf16_forward(torch::Tensor input, torch::Tensor weight);
"""
conv2d_bf16_ext = load_inline(
    name="conv2d_bf16_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["conv2d_bf16_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv2d submodule purely for parameter storage/naming
        # compatibility with the reference Model (path: conv1.weight).
        # We never call self.conv1.forward(); we only use its .weight tensor
        # inside our custom CUDA kernel.
        self.conv1 = nn.Conv2d(
            in_channels=3, out_channels=32, kernel_size=3,
            bias=False, dtype=torch.bfloat16
        )
    def forward(self, x):
        return conv2d_bf16_ext.conv2d_bf16_forward(x, self.conv1.weight)

